"use client"
import React from 'react'
import useOrderStore from '@/store/orderStore'
import Image from 'next/image'

function Page() {
  const { orders } = useOrderStore()
  return (
    <div>
      {orders && orders.length > 0 ? (
        orders.map((order, index) => (
          <div key={index}>
            <Image
              src={order.image}
              height={100}
              width={100}
              alt={order.name || "Order image"}
            />
            <h2>Product Name: {order.name}</h2>
            <h2>Full Name: {order.fullName}</h2>
            <h2>Province: {order.province}</h2>
            <h2>District: {order.district}</h2>
            <h2>City: {order.city}</h2>
            <h3>Order ID: {order.id}</h3>
            <h3>Order Date: {order.date}</h3>
            <h3>Order status: {order.status}</h3>
            <h3>Payment status:{order.paymentStatus}</h3>
            <h3>Total amount: {order.amount}</h3>
            <h3>Total quantity: {order.quantity}</h3>
            <hr />  
          </div>
        ))
      ) : (
        <p>No orders found.</p>
      )}
    </div>
  )
}

export default Page